import { test } from 'node:test';
import assert from 'node:assert/strict';
import { brotliDecompressSync } from 'node:zlib';
import { getScopedRecordReleaseDiff } from '../apps/web/lib/release-diffs';
import { v6SummaryAtRevision, v6ReviewedAnalysisOverride, type V6RecordPackage } from '../apps/web/lib/v6-effective-records';
import { getV6StudentActions } from '../apps/web/lib/policy-v6-student-actions';

process.env.UAPT_V6_PUBLISHED_PAGES = '1';
process.env.NEXT_PUBLIC_UAPT_V6_PUBLISHED_PAGES = '1';
process.env.UAPT_DISABLE_INTERNAL_FETCH = '1';

// Self-contained portable test fixture representing the 5 target schools from accepted candidate preparation
const FIXTURE_B64 = '';
const fixture: { candidateRecords: V6RecordPackage; candidatePagesSchools: any[] } = JSON.parse(
  brotliDecompressSync(Buffer.from(FIXTURE_B64, 'base64')).toString('utf8')
);
const candidateRecords = fixture.candidateRecords;
const candidatePagesSchools = fixture.candidatePagesSchools;

test('getScopedRecordReleaseDiff fail-closed on unknown revision', async () => {
  const result = await getScopedRecordReleaseDiff('unknown-revision-20269999');
  assert.equal(result, undefined);
});

test('getScopedRecordReleaseDiff fails closed on explicit unresolvable declared previous revision', async () => {
  const mockCorrection: V6RecordPackage = {
    schemaVersion: 'uapt-v6-effective-records-v1',
    revision: 'test-fail-closed-20261020',
    publishedAt: new Date().toISOString(),
    datasetReleaseId: 'public-release-20260924-002',
    publicationApproved: true,
    parentRevisionId: 'non-existent-parent-revision-99999',
    summaries: [{ entity: { slug: 'technical-university-of-munich' } } as any],
    snapshots: {},
    toolsBySlug: {},
    recordRevisions: {
      'technical-university-of-munich': {
        universityRevisionId: 'test-fail-closed-20261020',
        datasetReleaseId: 'public-release-20260924-002',
        recordSha256: 'mocksha256',
        publishedAt: new Date().toISOString(),
        previousRevisionId: 'non-existent-parent-revision-99999'
      }
    },
    heldBySlug: {},
    historical: {},
    aliasesBySlug: {},
    changesBySlug: {}
  };

  await assert.rejects(
    async () => {
      await getScopedRecordReleaseDiff('test-fail-closed-20261020', mockCorrection);
    },
    /Declared previous revision 'non-existent-parent-revision-99999' unavailable for entity 'technical-university-of-munich'/
  );
});

test('getScopedRecordReleaseDiff correctly resolves parent revision qs23-24-v6-r3-20261019', async () => {
  const diff = await getScopedRecordReleaseDiff('qs23-24-v6-r3-20261019');
  assert(diff, 'ReleaseDiff should be resolved for qs23-24-v6-r3-20261019');
  assert.equal(diff.publicationKind, 'scoped_record_correction');
  assert.equal(diff.releaseId, 'qs23-24-v6-r3-20261019');
  assert(diff.entities.length >= 2, 'Should contain at least TUM and JHU');

  const tum = diff.entities.find(e => e.entitySlug === 'technical-university-of-munich');
  assert(tum, 'TUM entity diff should exist');
  const jhu = diff.entities.find(e => e.entitySlug === 'jhu');
  assert(jhu, 'JHU entity diff should exist');
});

test('parent revision qs23-24-v6-r3-20261019 has exact summaries for all target schools', async () => {
  const tum = v6SummaryAtRevision('technical-university-of-munich', 'qs23-24-v6-r3-20261019');
  assert(tum, 'TUM summary must exist in parent');
  assert.equal(tum.claims.length, 14, 'TUM parent must have 14 claims');

  const unsw = v6SummaryAtRevision('unsw-sydney', 'qs23-24-v6-r3-20261019');
  assert(unsw, 'UNSW summary must exist in parent');
  assert.equal(unsw.claims.length, 40, 'UNSW parent must have 40 claims');

  const yale = v6SummaryAtRevision('yale-university', 'qs23-24-v6-r3-20261019');
  assert(yale, 'Yale summary must exist in parent');
  assert.equal(yale.claims.length, 31, 'Yale parent must have 31 claims');

  const epfl = v6SummaryAtRevision('epfl', 'qs23-24-v6-r3-20261019');
  assert(epfl, 'EPFL summary must exist in parent');
  assert.equal(epfl.claims.length, 14, 'EPFL parent must have 14 claims');

  const jhu = v6SummaryAtRevision('jhu', 'qs23-24-v6-r3-20261019');
  assert(jhu, 'JHU summary must exist in parent');
  assert.equal(jhu.claims.length, 16, 'JHU parent must have 16 claims');
});

test('candidate revision qs20-24-v6-r5-20261020 resolves exact diffs against parent qs23-24-v6-r3-20261019', async () => {
  const diff = await getScopedRecordReleaseDiff('qs20-24-v6-r5-20261020', candidateRecords);
  assert(diff, 'ReleaseDiff should resolve for qs20-24-v6-r5-20261020');
  assert.equal(diff.currentReleaseId, 'qs20-24-v6-r5-20261020');
  assert.equal(diff.previousReleaseId, 'qs23-24-v6-r3-20261019');

  // TUM check: 0 modified, 0 added, 0 removed
  const tum = diff.entities.find(e => e.entitySlug === 'technical-university-of-munich');
  assert(tum, 'TUM diff must exist');
  assert.equal(tum.rows.length, 0, 'TUM must have 0 changed claim rows against parent');

  // UNSW check: 0 modified, 0 added, 0 removed
  const unsw = diff.entities.find(e => e.entitySlug === 'unsw-sydney');
  assert(unsw, 'UNSW diff must exist');
  assert.equal(unsw.rows.length, 0, 'UNSW must have 0 changed claim rows against parent');

  // JHU check: policyTextChanged: 0, evidenceChanged: 4 across copilot tool claim
  const jhu = diff.entities.find(e => e.entitySlug === 'jhu');
  assert(jhu, 'JHU diff must exist');
  assert.equal(jhu.rows.length, 5, 'JHU must have 5 diff rows across copilot tool claim (1 modified, 2 added evidence, 2 removed evidence)');
  const modRow = jhu.rows.find(r => r.changeType === 'claim_modified');
  assert(modRow, 'JHU must have a claim_modified row');
  assert.equal(modRow.oldClaim?.claimText, modRow.newClaim?.claimText, 'JHU policy text must remain identical');
  const policyTextRows = jhu.rows.filter(r => r.changeCategory === 'policy_text_changed');
  assert.equal(policyTextRows.length, 0, 'JHU must have 0 policy_text_changed rows');
  const evidenceRows = jhu.rows.filter(r => r.changeCategory === 'evidence_changed');
  assert.equal(evidenceRows.length, 4, 'JHU must have 4 evidence_changed rows');

  // Yale check: policyTextChanged: 1, contains 5 business days
  const yale = diff.entities.find(e => e.entitySlug === 'yale-university');
  assert(yale, 'Yale diff must exist');
  assert.equal(yale.rows.length, 5, 'Yale must have 5 diff rows across GSAS procedure (1 modified, 4 added evidence)');
  const yaleMod = yale.rows.find(r => r.changeType === 'claim_modified');
  assert(yaleMod, 'Yale must have 1 claim_modified row');
  assert.equal(yaleMod.changeCategory, 'policy_text_changed');
  assert(yaleMod.newClaim?.claimText.includes('five business days'), 'Yale procedure must state five business days appeal deadline');
  assert.equal(yaleMod.newClaim?.evidence.length, 5, 'Yale procedure must have 5 source-linked evidence chunks');

  // EPFL check: policyTextChanged: 1, contains teaching chatbot quote
  const epfl = diff.entities.find(e => e.entitySlug === 'epfl');
  assert(epfl, 'EPFL diff must exist');
  assert.equal(epfl.rows.length, 3, 'EPFL must have 3 diff rows across Chatbot claim (1 modified, 1 added evidence, 1 removed evidence)');
  const epflMod = epfl.rows.find(r => r.changeType === 'claim_modified');
  assert(epflMod, 'EPFL must have 1 claim_modified row');
  assert.equal(epflMod.changeCategory, 'policy_text_changed');
  assert(epflMod.newClaim?.evidence[0].evidenceSnippet.includes('AI powered chatbot and semantic search of EPFL’s academic content'), 'EPFL Chatbot must have verbatim teaching quote');
});

test('getV6StudentActions returns active guide object for all 5 target universities', () => {
  for (const s of candidateRecords.summaries) {
    const slug = s.entity.slug;
    if (!['unsw-sydney', 'yale-university', 'epfl', 'technical-university-of-munich', 'jhu'].includes(slug)) continue;

    const pSchool = candidatePagesSchools.find((item: any) => item.slug === slug);
    assert(pSchool, `pSchool must exist for ${slug}`);

    const schoolMock: any = {
      ...pSchool,
      fingerprint: candidateRecords.recordRevisions[slug]?.recordSha256
    };

    const guide = getV6StudentActions(schoolMock, candidateRecords);
    assert(guide, `getV6StudentActions must return an active guide object for ${slug}`);
    assert.equal(guide.experience, 'compact_evidence');
    assert(Object.keys(guide.claims).length > 0, `Guide must contain claims for ${slug}`);

    if (slug === 'yale-university') {
      const gsas = guide.claims['draft-claim-yale-gsas-discipline-committee-procedure'];
      assert(gsas, 'Yale guide must contain draft-claim-yale-gsas-discipline-committee-procedure');
      assert.equal(gsas.evidence.length, 5, 'Yale GSAS procedure in guide must have 5 evidence items');
    }
    if (slug === 'epfl') {
      const chatbot = guide.claims['cl-epfl-ecole-polytechnique-federale-de-lausanne-institutional-ai-service-167'];
      assert(chatbot, 'EPFL guide must contain cl-epfl-ecole-polytechnique-federale-de-lausanne-institutional-ai-service-167');
      assert(chatbot.evidence[0].quote.includes('AI powered chatbot and semantic search'), 'EPFL guide must contain verbatim quote');
    }
    if (slug === 'jhu') {
      const copilot = guide.claims['cl-johns-hopkins-university-microsoft-copilot-for-m365-174'];
      assert(copilot, 'JHU guide must contain cl-johns-hopkins-university-microsoft-copilot-for-m365-174');
      assert.equal(copilot.evidence.length, 2, 'JHU Copilot guide must have 2 evidence items');
    }
  }
});

test('v6ReviewedAnalysisOverride returns proper structured dimensions and corrected UNSW dates', () => {
  for (const s of candidateRecords.summaries) {
    const slug = s.entity.slug;
    if (!['unsw-sydney', 'yale-university', 'epfl', 'technical-university-of-munich', 'jhu'].includes(slug)) continue;

    const dimensions = v6ReviewedAnalysisOverride(s, candidateRecords);
    assert(dimensions, `v6ReviewedAnalysisOverride must return dimensions for ${slug}`);
    assert.equal(Object.keys(dimensions).length, 11, `${slug} must have all 11 dimension keys`);

    for (const [dimKey, dimVal] of Object.entries(dimensions)) {
      assert(Array.isArray(dimVal.claimIds), `${slug} dimension ${dimKey} claimIds must be array`);
      assert(typeof dimVal.status === 'string', `${slug} dimension ${dimKey} status must be string`);
      assert(typeof dimVal.summary === 'string', `${slug} dimension ${dimKey} summary must be string`);
    }

    if (slug === 'unsw-sydney') {
      const courseworkSummary = dimensions.coursework?.summary;
      assert(courseworkSummary, 'UNSW coursework summary must exist');
      assert(
        courseworkSummary.includes('Term 3 2026') && courseworkSummary.includes('Semester 2 2026') && courseworkSummary.includes('Hexamester 1 2027'),
        `UNSW coursework summary must contain 2026 implementation dates: ${courseworkSummary}`
      );
    }
  }
});
